package com.ratbag24.reminders;

import com.google.inject.Provides;
import com.ratbag24.reminders.buff.BuffReminder;
import com.ratbag24.reminders.buff.BuffSettings;
import com.ratbag24.reminders.buff.Buffs;
import com.ratbag24.reminders.chat.ChatBuffReminder;
import com.ratbag24.reminders.chat.ChatBuffs;
import com.ratbag24.reminders.heart.SaturatedHeartReminder;
import com.ratbag24.reminders.visual.AlertBannerOverlay;
import com.ratbag24.reminders.visual.ItemFlashOverlay;
import com.ratbag24.reminders.visual.ScreenFlashOverlay;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * A single plugin for the small "don't forget to re-apply that" reminders, each
 * one switchable on its own.
 * <p>
 * The client's events are subscribed to once here and passed on to every
 * registered {@link Reminder}, so adding the next reminder means defining it
 * and listing it in {@link #startUp()} rather than touching the event plumbing.
 */
@PluginDescriptor(
	name = "All-in-One Reminders",
	description = "Reminds you when your saturated heart and other re-appliable buffs are ready",
	tags = {"heart", "saturated", "imbued", "thrall", "vengeance", "divine", "boost",
		"reminder", "timer", "cooldown", "buff"}
)
public class RemindersPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private AlertBannerOverlay alertBannerOverlay;

	@Inject
	private ScreenFlashOverlay screenFlashOverlay;

	@Inject
	private ItemFlashOverlay itemFlashOverlay;

	@Inject
	private CombatTracker combatTracker;

	@Inject
	private ReminderContext reminderContext;

	@Inject
	private RemindersConfig config;

	@Inject
	private SaturatedHeartReminder saturatedHeartReminder;

	private final List<Reminder> reminders = new ArrayList<>();

	@Provides
	RemindersConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RemindersConfig.class);
	}

	@Override
	protected void startUp()
	{
		// Register each reminder here. The rest of the plugin does not care
		// which ones exist.
		//
		// The heart has a class of its own because it tracks a cooldown with a
		// countdown and two possible hearts behind one varbit. Everything else
		// so far is a buff that is simply there or not, which one class covers:
		// a new one needs a definition in Buffs, a config section, and a line
		// here.
		reminders.add(saturatedHeartReminder);

		reminders.add(new BuffReminder(reminderContext, Buffs.THRALL, new BuffSettings(
			config::thrallEnabled,
			config::thrallNotification,
			config::thrallReminderOverlay,
			config::thrallOnlyInCombat)));

		reminders.add(new BuffReminder(reminderContext, Buffs.VENGEANCE, new BuffSettings(
			config::vengeanceEnabled,
			config::vengeanceNotification,
			config::vengeanceReminderOverlay,
			config::vengeanceOnlyInCombat)));

		reminders.add(new BuffReminder(reminderContext, Buffs.DIVINE_POTION, new BuffSettings(
			config::divineEnabled,
			config::divineNotification,
			config::divineReminderOverlay,
			config::divineOnlyInCombat)));

		reminders.add(new BuffReminder(reminderContext, Buffs.DEATH_CHARGE, new BuffSettings(
			config::deathChargeEnabled,
			config::deathChargeNotification,
			config::deathChargeReminderOverlay,
			config::deathChargeOnlyInCombat)));

		reminders.add(new BuffReminder(reminderContext, Buffs.SHADOW_VEIL, new BuffSettings(
			config::shadowVeilEnabled,
			config::shadowVeilNotification,
			config::shadowVeilReminderOverlay,
			config::shadowVeilOnlyInCombat)));

		reminders.add(new BuffReminder(reminderContext, Buffs.ANTIFIRE, new BuffSettings(
			config::antifireEnabled,
			config::antifireNotification,
			config::antifireReminderOverlay,
			config::antifireOnlyInCombat)));

		reminders.add(new BuffReminder(reminderContext, Buffs.STAMINA, new BuffSettings(
			config::staminaEnabled,
			config::staminaNotification,
			config::staminaReminderOverlay,
			config::staminaOnlyInCombat)));

		reminders.add(new BuffReminder(reminderContext, Buffs.MAGIC_IMBUE, new BuffSettings(
			config::magicImbueEnabled,
			config::magicImbueNotification,
			config::magicImbueReminderOverlay,
			config::magicImbueOnlyInCombat)));

		reminders.add(new BuffReminder(reminderContext, Buffs.MENAPHITE_REMEDY, new BuffSettings(
			config::menaphiteRemedyEnabled,
			config::menaphiteRemedyNotification,
			config::menaphiteRemedyReminderOverlay,
			config::menaphiteRemedyOnlyInCombat)));

		// These two have no varbit: they are timed from their chat message.
		reminders.add(new ChatBuffReminder(reminderContext, ChatBuffs.MARK_OF_DARKNESS,
			new BuffSettings(
				config::markOfDarknessEnabled,
				config::markOfDarknessNotification,
				config::markOfDarknessReminderOverlay,
				config::markOfDarknessOnlyInCombat)));

		reminders.add(new ChatBuffReminder(reminderContext, ChatBuffs.WARD_OF_ARCEUUS,
			new BuffSettings(
				config::wardOfArceuusEnabled,
				config::wardOfArceuusNotification,
				config::wardOfArceuusReminderOverlay,
				config::wardOfArceuusOnlyInCombat)));

		for (Reminder reminder : reminders)
		{
			reminder.startUp(this);
		}

		overlayManager.add(alertBannerOverlay);
		overlayManager.add(screenFlashOverlay);
		overlayManager.add(itemFlashOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(alertBannerOverlay);
		overlayManager.remove(screenFlashOverlay);
		overlayManager.remove(itemFlashOverlay);

		for (Reminder reminder : reminders)
		{
			reminder.shutDown();
		}

		reminders.clear();
		combatTracker.reset();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();

		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING
			|| state == GameState.CONNECTION_LOST)
		{
			// Nothing inferred from the last session can be trusted, and the
			// next value read must not be mistaken for a buff running out.
			combatTracker.reset();

			for (Reminder reminder : reminders)
			{
				reminder.reset();
			}
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		for (Reminder reminder : reminders)
		{
			reminder.onVarbitChanged(event);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		for (Reminder reminder : reminders)
		{
			reminder.onItemContainerChanged(event);
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		combatTracker.onHitsplatApplied(event);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		for (Reminder reminder : reminders)
		{
			reminder.onChatMessage(event);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		for (Reminder reminder : reminders)
		{
			reminder.onGameTick();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!RemindersConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		for (Reminder reminder : reminders)
		{
			reminder.onConfigChanged();
		}
	}

	/**
	 * Whether any enabled reminder is asking for attention, which is what the
	 * screen edge flash follows. Independent of the text panel, so the two can
	 * be switched on and off separately.
	 */
	public boolean isAnyReminderNudging()
	{
		for (Reminder reminder : reminders)
		{
			if (reminder.isNudging())
			{
				return true;
			}
		}

		return false;
	}

	/**
	 * What the alert banner should be shouting, one line per reminder that is
	 * currently nudging. Read on the client thread while the overlay renders.
	 */
	public List<String> getAlerts()
	{
		List<String> alerts = null;

		for (Reminder reminder : reminders)
		{
			final String alert = reminder.getAlertText();

			if (alert != null)
			{
				if (alerts == null)
				{
					alerts = new ArrayList<>(reminders.size());
				}

				alerts.add(alert);
			}
		}

		return alerts == null ? Collections.emptyList() : alerts;
	}

}

package com.ratbag24.reminders.buff;

/**
 * Everything that distinguishes one buff reminder from another: what it is
 * called, what to say about it, and which varbits report it.
 * <p>
 * Keeping this as data rather than a class per buff is what makes adding the
 * next reminder a constant in {@link Buffs}, a section in the config and one
 * line of registration.
 */
public final class BuffDefinition
{
	private final String notificationMessage;
	private final String alertText;
	private final int[] varbits;

	/**
	 * @param notificationMessage  the one-off message sent as it runs out
	 * @param alertText            the banner's wording, phrased as the thing to
	 *                             do rather than the state you are in
	 * @param varbits              every varbit that is non-zero while any part
	 *                             of the buff is still running
	 */
	public BuffDefinition(String notificationMessage, String alertText, int... varbits)
	{
		this.notificationMessage = notificationMessage;
		this.alertText = alertText;
		this.varbits = varbits.clone();
	}

	public String getNotificationMessage()
	{
		return notificationMessage;
	}

	public String getAlertText()
	{
		return alertText;
	}

	public int[] getVarbits()
	{
		return varbits.clone();
	}
}

package com.ratbag24.reminders.buff;

import com.ratbag24.reminders.Reminder;
import com.ratbag24.reminders.ReminderContext;
import javax.annotation.Nullable;
import net.runelite.api.events.VarbitChanged;

/**
 * Reminds the player that a buff has run out, for any buff the game reports
 * through varbits that are non-zero while it lasts.
 * <p>
 * One instance per buff, built from a {@link BuffDefinition}. The notification
 * fires once, on the buff running out; the banner, in contrast, reflects the
 * ongoing state of not having it, which also covers a buff that has been let
 * lapse rather than only one that just went.
 */
public class BuffReminder implements Reminder
{
	private final ReminderContext ctx;
	private final BuffDefinition definition;
	private final BuffSettings settings;
	private final BuffState state;

	public BuffReminder(ReminderContext ctx, BuffDefinition definition, BuffSettings settings)
	{
		this.ctx = ctx;
		this.definition = definition;
		this.settings = settings;
		this.state = new BuffState(definition.getVarbits());
	}

	@Override
	public boolean isEnabled()
	{
		return settings.isEnabled();
	}

	@Override
	public void reset()
	{
		state.reset();
	}

	@Override
	public void onVarbitChanged(VarbitChanged event)
	{
		// The buff is tracked even while its reminder is switched off, so that
		// switching it on does not need a re-login to read right.
		final BuffState.Transition transition =
			state.onVarbitValue(event.getVarbitId(), event.getValue());

		if (transition == BuffState.Transition.EXPIRED && isEnabled() && conditionsMet())
		{
			ctx.announce(settings.getNotification(), definition.getNotificationMessage());
		}
	}

	@Override
	public void onGameTick()
	{
		if (!state.isSynced())
		{
			// Seed every watched varbit together on the first tick after
			// logging in. Adopting them this way never counts as an expiry.
			final int[] varbits = state.getVarbits();
			final int[] values = new int[varbits.length];

			for (int i = 0; i < varbits.length; i++)
			{
				values[i] = ctx.getClient().getVarbitValue(varbits[i]);
			}

			state.sync(values);
		}
	}

	@Override
	public boolean isNudging()
	{
		if (!isEnabled() || !state.isSynced() || state.isActive())
		{
			return false;
		}

		// Nothing is said to a player who has not had this buff up at all: not
		// having cast vengeance is the normal state for most of the game.
		return state.hasBeenActive() && conditionsMet();
	}

	@Nullable
	@Override
	public String getAlertText()
	{
		return isNudging() && settings.isShowReminder() ? definition.getAlertText() : null;
	}

	private boolean conditionsMet()
	{
		return !settings.isOnlyInCombat() || ctx.isInCombat();
	}
}

package com.ratbag24.reminders.buff;

import java.util.function.BooleanSupplier;
import java.util.function.Supplier;
import net.runelite.client.config.Notification;

/**
 * One buff's settings, read live from the config.
 * <p>
 * The settings are passed as suppliers rather than values so that a buff
 * reminder reads whatever the user has set at the moment it matters, without
 * every reminder needing to know about the config interface.
 */
public final class BuffSettings
{
	private final BooleanSupplier enabled;
	private final Supplier<Notification> notification;
	private final BooleanSupplier showReminder;
	private final BooleanSupplier onlyInCombat;

	public BuffSettings(BooleanSupplier enabled, Supplier<Notification> notification,
		BooleanSupplier showReminder, BooleanSupplier onlyInCombat)
	{
		this.enabled = enabled;
		this.notification = notification;
		this.showReminder = showReminder;
		this.onlyInCombat = onlyInCombat;
	}

	public boolean isEnabled()
	{
		return enabled.getAsBoolean();
	}

	public Notification getNotification()
	{
		return notification.get();
	}

	public boolean isShowReminder()
	{
		return showReminder.getAsBoolean();
	}

	public boolean isOnlyInCombat()
	{
		return onlyInCombat.getAsBoolean();
	}
}

package com.ratbag24.reminders.buff;

import java.util.Arrays;

/**
 * Tracks a buff that the game reports through one or more varbits, each
 * non-zero for as long as some part of the buff is still running.
 * <p>
 * One shape covers every buff the plugin reminds about besides the heart:
 * <ul>
 *     <li>a thrall, whose single varbit drops to zero when it expires;</li>
 *     <li>vengeance, which is ready to cast once both its cooldown and its
 *     cast-and-waiting varbit are zero;</li>
 *     <li>divine potions, where one potion sets several varbits at once, so the
 *     boost is only really gone when the last of them reaches zero.</li>
 * </ul>
 * Waiting for <em>all</em> of them is what keeps a divine super combat potion
 * from reminding four times as its separate stat timers run out.
 * <p>
 * Like {@link com.ratbag24.reminders.heart.HeartCooldown} this has no RuneLite
 * dependencies, so the rules can be unit tested on their own.
 */
public final class BuffState
{
	/** What a varbit change meant relative to the state before it. */
	public enum Transition
	{
		/** Nothing worth acting on, or a varbit this buff does not watch. */
		NONE,
		/** The buff started, or was re-applied while still running. */
		ACTIVE,
		/** The last of the watched varbits reached zero: the buff is gone. */
		EXPIRED
	}

	private final int[] varbits;
	private final int[] values;
	private boolean synced;
	private boolean seenActive;

	public BuffState(int... varbits)
	{
		if (varbits.length == 0)
		{
			throw new IllegalArgumentException("a buff must watch at least one varbit");
		}

		this.varbits = varbits.clone();
		this.values = new int[varbits.length];
	}

	public int[] getVarbits()
	{
		return varbits.clone();
	}

	/**
	 * Adopts the current value of every watched varbit without reporting a
	 * transition. Called on the first tick after logging in: a buff that was
	 * already running, or already gone, is the state we join, not a change we
	 * should announce.
	 *
	 * @param currentValues one value per varbit, in the order given to the
	 *                      constructor
	 */
	public void sync(int[] currentValues)
	{
		if (currentValues.length != values.length)
		{
			throw new IllegalArgumentException(
				"expected " + values.length + " values, got " + currentValues.length);
		}

		for (int i = 0; i < values.length; i++)
		{
			values[i] = Math.max(0, currentValues[i]);
		}

		synced = true;
		seenActive |= isActive();
	}

	/**
	 * Feeds in a varbit change.
	 *
	 * @param varbitId the varbit that changed, watched or not
	 * @param value    its new value
	 * @return what the change meant
	 */
	public Transition onVarbitValue(int varbitId, int value)
	{
		final int index = indexOf(varbitId);

		if (index < 0)
		{
			return Transition.NONE;
		}

		if (!synced)
		{
			// Values are seeded together on the first tick after login, so a
			// change arriving before that would be read against zeroes we have
			// not confirmed. Record it and say nothing.
			values[index] = Math.max(0, value);
			return Transition.NONE;
		}

		final boolean wasActive = isActive();
		values[index] = Math.max(0, value);
		final boolean nowActive = isActive();

		if (nowActive)
		{
			seenActive = true;
			return wasActive ? Transition.NONE : Transition.ACTIVE;
		}

		return wasActive ? Transition.EXPIRED : Transition.NONE;
	}

	/** Forgets everything, so the next sync is treated as a fresh join. */
	public void reset()
	{
		synced = false;
		seenActive = false;
		Arrays.fill(values, 0);
	}

	public boolean isSynced()
	{
		return synced;
	}

	/**
	 * Whether the buff has been up at all since logging in.
	 * <p>
	 * For most buffs, not having one is the normal state of a player who never
	 * uses it: vengeance is uncast for everyone who does not cast vengeance. A
	 * standing reminder is only worth showing to someone who has shown they
	 * want the buff by applying it at least once.
	 */
	public boolean hasBeenActive()
	{
		return seenActive;
	}

	/** Whether any part of the buff is still running. */
	public boolean isActive()
	{
		for (int value : values)
		{
			if (value > 0)
			{
				return true;
			}
		}

		return false;
	}

	private int indexOf(int varbitId)
	{
		for (int i = 0; i < varbits.length; i++)
		{
			if (varbits[i] == varbitId)
			{
				return i;
			}
		}

		return -1;
	}
}

package com.ratbag24.reminders.buff;

import net.runelite.api.gameval.VarbitID;

/**
 * The buffs the plugin reminds about, beyond the heart.
 * <p>
 * Each one is watched through the varbits the game keeps for it, and is treated
 * as gone once every one of them has reached zero. Adding another is a constant
 * here, a config section, and a line in the plugin's registry.
 * <p>
 * Ward of Arceuus and Mark of Darkness live in the chat package instead: the
 * game gives them no varbit while they are up, so they have to be timed from
 * the chat line that announces them.
 * <p>
 * Where a spell has a cooldown of its own, that varbit is watched alongside the
 * one saying the buff is up. A buff can be gone while the spell that applies it
 * is still unavailable, and telling someone to cast something they cannot cast
 * is worse than saying nothing.
 */
public final class Buffs
{
	/**
	 * A thrall lasts one tick per Magic level, doubled at Grandmaster combat
	 * achievement tier, and its varbit drops to zero the moment it leaves.
	 * <p>
	 * The cooldown is watched alongside it so the reminder cannot ask for a
	 * thrall that cannot yet be summoned.
	 */
	public static final BuffDefinition THRALL = new BuffDefinition(
		"Your thrall has expired.",
		"You need a thrall!",
		VarbitID.ARCEUUS_RESURRECTION_ACTIVE,
		VarbitID.ARCEUUS_RESURRECTION_COOLDOWN);

	/**
	 * Vengeance can only be re-cast once its cooldown has run out <em>and</em>
	 * the cast it is holding has rebounded, so both have to be clear before
	 * there is anything worth saying.
	 */
	public static final BuffDefinition VENGEANCE = new BuffDefinition(
		"Vengeance is ready to cast.",
		"You need vengeance!",
		VarbitID.VENGEANCE_TIMELIMIT,
		VarbitID.VENGEANCE_REBOUND);

	/**
	 * A single divine potion sets its own timer and one per stat it boosts, so
	 * all of them are watched together: reminding as each stat timer ran out
	 * would fire several times for one potion.
	 */
	public static final BuffDefinition DIVINE_POTION = new BuffDefinition(
		"Your divine potion has worn off.",
		"You need a divine potion!",
		VarbitID.DIVINECOMBAT_POTION_TIME,
		VarbitID.DIVINEATTACK_POTION_TIME,
		VarbitID.DIVINESTRENGTH_POTION_TIME,
		VarbitID.DIVINEDEFENCE_POTION_TIME,
		VarbitID.DIVINERANGE_POTION_TIME,
		VarbitID.DIVINEMAGIC_POTION_TIME,
		VarbitID.DIVINEBASTION_POTION_TIME,
		VarbitID.DIVINEBATTLEMAGE_POTION_TIME);

	/**
	 * Death charge is spent on kills rather than by running down a clock — one
	 * kill, or two with the Book of the Dead — and the spell then sits on a
	 * minute's cooldown regardless.
	 * <p>
	 * Watching the charge alone announced "you need to death charge" the moment
