package com.ratbag24.reminders.chat;

/**
 * Tracks a buff the game never reports a state for, only announces in chat.
 * <p>
 * Mark of Darkness and Ward of Arceuus have no varbit saying whether they are
 * up. All the game gives is a line of chat when you cast one, so the only way
 * to know is to start a clock on that line and run it for as long as the spell
 * is known to last. RuneLite's own timers for these two work exactly this way.
 * <p>
 * That makes this less certain than a varbit, in two ways worth being honest
 * about:
 * <ul>
 *     <li>the duration is a rule about the spell rather than something the game
 *     confirms, so a change to the spell would silently make it wrong;</li>
 *     <li>logging in with one already running is invisible — there was no chat
 *     line to see — so tracking only begins at the next cast.</li>
 * </ul>
 * Neither can be fixed from outside the game. What can be avoided is claiming
 * to know more than we do, so an untracked buff stays silent rather than
 * guessing that it has expired.
 * <p>
 * Counted in game ticks rather than wall clock: the duration is given in ticks,
 * and ticks do not run while the client is logged out.
 */
public final class TimedBuffState
{
	/** No cast has been seen, so there is no clock running. */
	private static final int NOT_RUNNING = Integer.MIN_VALUE;

	public enum Transition
	{
		/** Nothing worth acting on. */
		NONE,
		/** The clock just ran out: the buff is gone. */
		EXPIRED
	}

	private int expiryTick = NOT_RUNNING;
	private boolean seenActive;

	/**
	 * Starts the clock, as of a cast seen in chat.
	 *
	 * @param nowTick        the client's current tick count
	 * @param durationTicks  how long the spell lasts
	 */
	public void start(int nowTick, int durationTicks)
	{
		if (durationTicks <= 0)
		{
			// A duration of nothing is not a cast worth tracking.
			return;
		}

		expiryTick = nowTick + durationTicks;
		seenActive = true;
	}

	/**
	 * Advances the clock.
	 *
	 * @return {@link Transition#EXPIRED} on the one tick the buff runs out
	 */
	public Transition onTick(int nowTick)
	{
		if (expiryTick == NOT_RUNNING || nowTick - expiryTick < 0)
		{
			return Transition.NONE;
		}

		// Cleared so the expiry is reported once, not on every tick after.
		expiryTick = NOT_RUNNING;
		return Transition.EXPIRED;
	}

	/** Whether the buff is believed to still be running. */
	public boolean isActive()
	{
		return expiryTick != NOT_RUNNING;
	}

	/**
	 * Whether a cast has been seen at all since logging in. Nothing is said
	 * about a spell the player has not shown any interest in.
	 */
	public boolean hasBeenActive()
	{
		return seenActive;
	}

	/**
	 * Forgets the clock. Called on login and on hopping: a cast from before is
	 * not something this can still time, and pretending otherwise would expire
	 * a buff that may well still be up.
	 */
	public void reset()
	{
		expiryTick = NOT_RUNNING;
		seenActive = false;
	}
}

package com.ratbag24.reminders.heart;

/**
 * Tracks the shared imbued/saturated heart cooldown from its varbit.
 * <p>
 * The varbit counts down in steps of ten game ticks, so it only gives us the
 * remaining time to the nearest six seconds. The value is therefore used for
 * two different jobs: the step down to zero is the authoritative "the heart has
 * recharged" event, while a wall clock estimate, re-synchronised on every step,
 * provides a display countdown that moves once a second instead of in six
 * second jumps.
 * <p>
 * This class deliberately has no RuneLite dependencies so that the timing rules
 * can be unit tested on their own.
 */
public final class HeartCooldown
{
	/** The cooldown varbit decrements once every ten game ticks. */
	public static final int TICKS_PER_UNIT = 10;
	public static final int MILLIS_PER_TICK = 600;
	public static final int MILLIS_PER_UNIT = TICKS_PER_UNIT * MILLIS_PER_TICK;

	/** The saturated heart's five minute cooldown, in varbit units. */
	public static final int SATURATED_UNITS = 50;
	/** The imbued heart's seven minute cooldown, in varbit units. */
	public static final int IMBUED_UNITS = 70;

	/**
	 * A fresh cooldown can be read a step or two after the game set it, so the
	 * starting value is matched to the nearest of the two known lengths rather
	 * than exactly. Anything this far below the shorter of the two is too short
	 * to have come from either heart.
	 */
	private static final int CLASSIFY_SLACK = 5;

	/** What a varbit value meant relative to the one before it. */
	public enum Transition
	{
		/** The value did not say anything worth acting on. */
		NONE,
		/** First value seen since logging in; the state was adopted, not entered. */
		SYNCED,
		/** A heart was just invigorated, or re-invigorated early. */
		STARTED,
		/** The cooldown ran out: the heart can be used again. */
		READY
	}

	private boolean synced;
	private int units;
	private HeartType type = HeartType.UNKNOWN;
	private long readyAtMillis;

	/**
	 * Feeds a new value of the cooldown varbit in.
	 *
	 * @param value      the raw varbit value, in units of ten game ticks
	 * @param nowMillis  the current wall clock time
	 * @return what the change meant
	 */
	public Transition onVarbitValue(int value, long nowMillis)
	{
		final int previous = units;
		units = Math.max(0, value);

		if (!synced)
		{
			// The first value after a login tells us the state the account was
			// already in. Announcing a heart as ready here would fire on every
			// login, so the value is only adopted.
			synced = true;
			type = units > 0 ? classifyPartial(units) : HeartType.UNKNOWN;
			readyAtMillis = units > 0 ? nowMillis + (long) units * MILLIS_PER_UNIT : 0L;
			return Transition.SYNCED;
		}

		if (units > 0)
		{
			readyAtMillis = nowMillis + (long) units * MILLIS_PER_UNIT;

			// Going up can only mean a heart was just used: either the cooldown
			// was at zero, or it was refreshed before it ran out.
			if (units > previous)
			{
				type = classifyFresh(units);
				return Transition.STARTED;
			}

			return Transition.NONE;
		}

		readyAtMillis = 0L;
		return previous > 0 ? Transition.READY : Transition.NONE;
	}

	/**
	 * Forgets everything known about the cooldown. Called when the player logs
	 * out or hops, so that the next value read is treated as a fresh sync
	 * rather than as a change.
	 */
	public void reset()
	{
		synced = false;
		units = 0;
		type = HeartType.UNKNOWN;
		readyAtMillis = 0L;
	}

	/**
	 * Narrows an unknown heart down to the saturated one. The game keeps its own
	 * varbit for the saturated heart's boost, and that only ever moves for a
	 * saturated heart, so it can identify a cooldown we joined partway through.
	 */
	public void markSaturated()
	{
		if (type == HeartType.UNKNOWN)
		{
			type = HeartType.SATURATED;
		}
	}

	public boolean isOnCooldown()
	{
		return units > 0;
	}

	public boolean isSynced()
	{
		return synced;
	}

	public int getUnits()
	{
		return units;
	}

	public HeartType getType()
	{
		return type;
	}

	/**
	 * How long until the heart recharges, for display. Held at one second while
	 * the cooldown is still running so that a countdown never reads as finished
	 * before the varbit says it is.
	 */
	public long getRemainingMillis(long nowMillis)
	{
		if (units <= 0)
		{
			return 0L;
		}

		final long remaining = readyAtMillis - nowMillis;
		final long cap = (long) units * MILLIS_PER_UNIT;
		return Math.min(cap, Math.max(1000L, remaining));
	}

	/** Matches a just-started cooldown to whichever heart's length is closer. */
	private static HeartType classifyFresh(int value)
	{
		if (value < SATURATED_UNITS - CLASSIFY_SLACK)
		{
			// Too short to be either heart's full cooldown.
			return HeartType.UNKNOWN;
		}

		final int toSaturated = Math.abs(value - SATURATED_UNITS);
		final int toImbued = Math.abs(value - IMBUED_UNITS);
		return toImbued < toSaturated ? HeartType.IMBUED : HeartType.SATURATED;
	}

	/**
	 * Identifies a cooldown that was already running. Only a value longer than
	 * the saturated heart's entire cooldown rules that heart out.
	 */
	private static HeartType classifyPartial(int value)
	{
		return value > SATURATED_UNITS ? HeartType.IMBUED : HeartType.UNKNOWN;
	}
}

package com.ratbag24.reminders.heart;

import java.awt.Color;
import java.awt.image.BufferedImage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/**
 * Counts the heart's remaining cooldown down in the infobox row.
 * <p>
 * The text is driven straight off {@link HeartCooldown} rather than off a
 * wall clock of its own, so it stays in step with the game even after a
 * logout, a world hop or a death reset.
 */
class HeartInfoBox extends InfoBox
{
	/** Below this the countdown turns green: time to get the next one ready. */
	private static final long NEARLY_READY_MILLIS = 30_000L;

	private final HeartCooldown cooldown;

	HeartInfoBox(BufferedImage image, Plugin plugin, HeartCooldown cooldown)
	{
		super(image, plugin);
		this.cooldown = cooldown;
	}

	@Override
	public String getText()
	{
		final long remaining = cooldown.getRemainingMillis(System.currentTimeMillis());
		final long totalSeconds = (remaining + 999L) / 1000L;
		return String.format("%d:%02d", totalSeconds / 60L, totalSeconds % 60L);
	}

	@Override
	public Color getTextColor()
	{
		final long remaining = cooldown.getRemainingMillis(System.currentTimeMillis());
		return remaining <= NEARLY_READY_MILLIS ? Color.GREEN.brighter() : Color.WHITE;
	}

	@Override
	public boolean render()
	{
		return cooldown.isOnCooldown();
	}
}

package com.ratbag24.reminders.heart;

/**
 * Which heart the tracked cooldown belongs to.
 * <p>
 * The imbued and saturated hearts share a single cooldown varbit, so the heart
 * in use can only be told apart by how long that cooldown started out: seven
 * minutes for the imbued heart, five for the saturated one. When the cooldown
 * was already running before we started watching it, neither length can be
 * ruled out and the type stays {@link #UNKNOWN}.
 */
public enum HeartType
{
	UNKNOWN("Heart"),
	IMBUED("Imbued heart"),
	SATURATED("Saturated heart");

	private final String displayName;

	HeartType(String displayName)
	{
		this.displayName = displayName;
	}

	public String getDisplayName()
	{
		return displayName;
	}
}

package com.ratbag24.reminders.heart;

import com.ratbag24.reminders.Reminder;
import com.ratbag24.reminders.ReminderContext;
import com.ratbag24.reminders.RemindersConfig;
import java.util.Locale;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Reminds the player that their saturated (or imbued) heart is ready again.
 * <p>
 * Both hearts count down the same varbit, so this one reminder covers either.
 * The varbit stepping to zero is treated as the authoritative "recharged"
 * event; the on-screen reminder, in contrast, reflects the ongoing state of
 * having a usable heart, which also covers a heart you have not got round to
 * using yet.
 */
@Singleton
public class SaturatedHeartReminder implements Reminder
{
	private final HeartCooldown cooldown = new HeartCooldown();

	@Inject
	private ReminderContext ctx;

	@Inject
	private RemindersConfig config;

	@Inject
	private InfoBoxManager infoBoxManager;

	@Inject
	private ItemManager itemManager;

	private Plugin plugin;
	private HeartInfoBox infoBox;
	private int infoBoxItemId;

	@Override
	public boolean isEnabled()
	{
		return config.heartEnabled();
	}

	@Override
	public void startUp(Plugin plugin)
	{
		this.plugin = plugin;
	}

	@Override
	public void shutDown()
	{
		removeInfoBox();
		cooldown.reset();
		plugin = null;
	}

	@Override
	public void reset()
	{
		cooldown.reset();
		removeInfoBox();
	}

	@Override
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.SATURATED_HEART_TIME && event.getValue() > 0)
		{
			// Only a saturated heart moves this one, which is enough to put a
			// name to a cooldown that was already running when we logged in.
			cooldown.markSaturated();
			syncInfoBox();
			return;
		}

		if (event.getVarbitId() != VarbitID.IMBUED_HEART_TIMER)
		{
			return;
		}

		// The cooldown is tracked even while the reminder is switched off, so
		// that switching it on mid-cooldown shows the right time straight away.
		final HeartCooldown.Transition transition =
			cooldown.onVarbitValue(event.getValue(), System.currentTimeMillis());

		if (transition == HeartCooldown.Transition.READY)
		{
			announceReady();
		}

		syncInfoBox();
	}

	@Override
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV)
		{
			// Banking a heart, or taking one out, changes whether the timer
			// should be on screen.
			syncInfoBox();
		}
	}

	@Override
	public void onGameTick()
	{
		if (!cooldown.isSynced())
		{
			// Seed from the current value on the first tick after logging in.
			// Adopting the value this way never counts as the heart recharging.
			cooldown.onVarbitValue(ctx.getClient().getVarbitValue(VarbitID.IMBUED_HEART_TIMER),
				System.currentTimeMillis());
			syncInfoBox();
		}
	}

	@Override
	public void onConfigChanged()
	{
		syncInfoBox();
	}

	@Override
	public boolean isNudging()
	{
		if (!isEnabled() || !cooldown.isSynced() || cooldown.isOnCooldown())
		{
			return false;
		}

		return isTracked() && conditionsMet();
	}

	@Nullable
	@Override
	public String getAlertText()
	{
		return isNudging() && config.heartReminderOverlay()
			? "Your " + lowerCaseName() + " is ready!"
			: null;
	}

	/**
	 * Whether an item sitting in the inventory should be highlighted right now.
	 * Asked by the item overlay, so that which hearts count stays here rather
	 * than being worked out twice.
	 */
	public boolean shouldFlashItem(int itemId)
	{
		if (!config.heartItemFlash() || !isNudging())
		{
			return false;
		}

		if (itemId == ItemID.SATURATED_HEART)
		{
			return true;
		}

		return config.heartTrackedHearts() == TrackedHearts.BOTH
			&& itemId == ItemID.IMBUED_HEART;
	}

	private void announceReady()
	{
		if (!isEnabled() || !isTracked() || !conditionsMet())
		{
			return;
		}

		ctx.announce(config.heartNotification(),
			"Your " + lowerCaseName() + " has recharged.");
	}

	private String lowerCaseName()
	{
		return cooldown.getType().getDisplayName().toLowerCase(Locale.ENGLISH);
	}

	/** Whether the heart on cooldown is one the user asked to be reminded about. */
	private boolean isTracked()
	{
		return config.heartTrackedHearts().includes(cooldown.getType());
	}

	private boolean conditionsMet()
	{
		if (config.heartRequireInInventory() && !carryingHeart())
		{
			return false;
		}

		return !config.heartOnlyInCombat() || ctx.isInCombat();
	}

	private boolean carryingHeart()
	{
		final ItemContainer inventory = ctx.getClient().getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return false;
		}

		if (inventory.contains(ItemID.SATURATED_HEART))
		{
			return true;
		}

		// An imbued heart only counts when imbued hearts are being tracked.
		return config.heartTrackedHearts() == TrackedHearts.BOTH
			&& inventory.contains(ItemID.IMBUED_HEART);
	}

	/**
	 * Brings the infobox in line with the settings and the cooldown. Called
	 * after anything that could change either, so there is one place that
	 * decides whether the timer should be on screen.
	 */
	private void syncInfoBox()
	{
		// The timer follows "only when carrying one" but deliberately not "only
		// while fighting": a countdown that vanished between kills would be
		// worse than no countdown at all.
		final boolean wanted = isEnabled()
			&& config.heartTimer()
			&& cooldown.isOnCooldown()
			&& isTracked()
			&& (!config.heartRequireInInventory() || carryingHeart());

		if (!wanted)
		{
			removeInfoBox();
			return;
		}

		final int itemId = heartItemId();

		if (infoBox != null && infoBoxItemId == itemId)
		{
			// The heart may have been identified since the box went up, in
			// which case only the wording needs catching up.
			infoBox.setTooltip(tooltip());
			return;
		}

		// A heart identified part way through a cooldown leaves the infobox
		// showing the other heart's icon, so it is rebuilt rather than reused.
		removeInfoBox();
		addInfoBox(itemId);
	}

	private void addInfoBox(int itemId)
	{
		if (plugin == null)
		{
			return;
		}

		final AsyncBufferedImage image = itemManager.getImage(itemId);
		final HeartInfoBox box = new HeartInfoBox(image, plugin, cooldown);
		box.setTooltip(tooltip());

		infoBox = box;
		infoBoxItemId = itemId;
		infoBoxManager.addInfoBox(box);

		// Item images load off the client thread; refresh once it arrives.
		image.onLoaded(() ->
		{
			if (infoBox == box)
			{
				box.setImage(image);
				infoBoxManager.updateInfoBoxImage(box);
			}
		});
	}

	private void removeInfoBox()
	{
		if (infoBox != null)
		{
			infoBoxManager.removeInfoBox(infoBox);
			infoBox = null;
			infoBoxItemId = 0;
		}
	}

	private String tooltip()
	{
		return cooldown.getType().getDisplayName() + " cooldown";
	}

	private int heartItemId()
	{
		return cooldown.getType() == HeartType.IMBUED
			? ItemID.IMBUED_HEART
			: ItemID.SATURATED_HEART;
	}
}

package com.ratbag24.reminders.heart;

/** Which of the two hearts the reminder should fire for. */
public enum TrackedHearts
{
	BOTH("Imbued and saturated"),
	SATURATED_ONLY("Saturated only");

	private final String displayName;

	TrackedHearts(String displayName)
	{
		this.displayName = displayName;
	}

	/** Whether a cooldown belonging to this heart should be reminded about. */
	public boolean includes(HeartType type)
	{
		// An unidentified heart gets the benefit of the doubt: a reminder that
		// occasionally fires for the wrong heart beats one that silently never
		// fires because the cooldown was already running at login.
		return this == BOTH || type != HeartType.IMBUED;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.ratbag24.reminders.visual;

import com.ratbag24.reminders.RemindersConfig;
import com.ratbag24.reminders.RemindersPlugin;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A banner saying what to do about it, in white on red, for anything currently
 * asking for attention.
 * <p>
 * This is the loud one. The status panel tells you how things stand and the
 * screen edge tells you something is wrong; this says which thing and what to
 * do, in words, big enough to read without looking away from the fight. Drag it
 * wherever suits.
 */
public class AlertBannerOverlay extends Overlay
{
	private static final int PAD_X = 8;
	private static final int PAD_Y = 3;
	/** Gap between stacked banners when more than one thing is down. */
	private static final int GAP = 3;

	private final RemindersPlugin plugin;
	private final RemindersConfig config;

	@Inject
	private AlertBannerOverlay(RemindersPlugin plugin, RemindersConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.alertBanner())
		{
			return null;
		}

		final List<String> alerts = plugin.getAlerts();

		if (alerts.isEmpty())
		{
			return null;
		}

		graphics.setFont(config.bannerFont().getFont());

		final FontMetrics metrics = graphics.getFontMetrics();
		final Color background = config.alertColour();
		// Darker rather than lighter: it holds the banner's shape against a
		// bright scene, where a pale outline washes out.
		final Color border = background.darker();

		int width = 0;

		for (String alert : alerts)
		{
			width = Math.max(width, metrics.stringWidth(alert));
		}

		width += PAD_X * 2;

		final int lineHeight = metrics.getHeight() + PAD_Y * 2;
		int y = 0;

		for (String alert : alerts)
		{
			graphics.setColor(background);
			graphics.fillRect(0, y, width, lineHeight);
			graphics.setColor(border);
			graphics.drawRect(0, y, width - 1, lineHeight - 1);

			final int textX = (width - metrics.stringWidth(alert)) / 2;
			final int textY = y + PAD_Y + metrics.getAscent();

			// Drawn twice: the game's background can be any colour, and a plain
			// white string over a bright scene is hard to read without it.
			graphics.setColor(Color.BLACK);
			graphics.drawString(alert, textX + 1, textY + 1);
			graphics.setColor(Color.WHITE);
			graphics.drawString(alert, textX, textY);

			y += lineHeight + GAP;
		}

		// The trailing gap is not part of the banner.
		return new Dimension(width, y - GAP);
	}
}

package com.ratbag24.reminders.visual;

import java.awt.Font;
import net.runelite.client.ui.FontManager;

/**
 * Which of the game's own typefaces the alert banner is drawn in, and so how
 * big the banner ends up.
 * <p>
 * These are the three faces RuneLite ships rather than a size in points. They
 * are bitmap faces drawn at a fixed size, so scaling one would make it fuzzy;
 * picking between them keeps the banner looking like it belongs to the game.
 */
public enum BannerFont
{
	SMALL("Small"),
	REGULAR("Regular"),
	LARGE("Large");

	private final String displayName;

	BannerFont(String displayName)
	{
		this.displayName = displayName;
	}

	/** The font itself. Resolved at render time, never cached. */
	public Font getFont()
	{
		switch (this)
		{
			case SMALL:
				return FontManager.getRunescapeSmallFont();
			case LARGE:
				return FontManager.getRunescapeBoldFont();
			default:
				return FontManager.getRunescapeFont();
		}
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.ratbag24.reminders.visual;

import com.ratbag24.reminders.RemindersConfig;
import com.ratbag24.reminders.heart.SaturatedHeartReminder;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Throbs the heart in the inventory while it is ready to be invigorated, so the
 * thing to click is the thing that is lit up.
 * <p>
 * Only the heart is highlighted: a thrall and vengeance are spells rather than
 * items, and there is nothing in the inventory to point at.
 */
public class ItemFlashOverlay extends WidgetItemOverlay
{
	/** How strongly the slot itself is washed, against the outline's full strength. */
	private static final double WASH = 0.35;

	private final SaturatedHeartReminder heartReminder;
	private final RemindersConfig config;

	@Inject
	private ItemFlashOverlay(SaturatedHeartReminder heartReminder, RemindersConfig config)
	{
		this.heartReminder = heartReminder;
		this.config = config;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		// Which items count, and whether anything should be lit at all, is the
		// heart reminder's business.
		if (!heartReminder.shouldFlashItem(itemId))
		{
			return;
		}

		final Rectangle bounds = widgetItem.getCanvasBounds();

		if (bounds == null)
		{
			return;
		}

		final long now = System.currentTimeMillis();
		final Color colour = config.flashColour();

		graphics.setColor(Pulse.fade(colour, now, WASH));
		graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);

		graphics.setColor(Pulse.fade(colour, now));
		graphics.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
	}
}

package com.ratbag24.reminders.visual;

import java.awt.Color;

/**
 * The slow throb shared by every visual the plugin draws, so the screen edge
 * and a highlighted item rise and fall together rather than beating against
 * each other.
 * <p>
 * It is a smooth sine rather than a blink, and deliberately slow. A hard
 * on/off flash at a few hertz is both harder to ignore for everyone and a
 * genuine problem for photosensitive players; one cycle every 1.4 seconds
 * reads as "look here" without strobing.
 * <p>
 * No RuneLite dependencies, so the curve can be unit tested.
 */
public final class Pulse
{
	/** One full dim-bright-dim cycle, in milliseconds. */
	public static final long PERIOD_MILLIS = 1400L;

	/** How faint the pulse goes at its dimmest, as a fraction of full strength. */
	private static final double TROUGH = 0.35;

	/**
	 * The pulse strength at a moment in time, between {@link #TROUGH} and 1.
	 *
	 * @param nowMillis the current wall clock time
	 */
	public static double strength(long nowMillis)
	{
		// floorMod keeps the phase correct for a clock that reads negative.
		final double phase = Math.floorMod(nowMillis, PERIOD_MILLIS) / (double) PERIOD_MILLIS;

		// A raised cosine: starts at the trough, peaks half way through, and
		// meets itself smoothly at the end of the cycle.
		final double wave = (1.0 - Math.cos(phase * 2.0 * Math.PI)) / 2.0;

		return TROUGH + (1.0 - TROUGH) * wave;
	}

	/**
	 * The given colour with its alpha scaled by the pulse, and optionally by a
	 * further factor for a soft edge.
	 *
	 * @param base      the colour to pulse, whose own alpha sets the maximum
	 * @param nowMillis the current wall clock time
	 * @param falloff   an extra multiplier between 0 and 1
	 */
	public static Color fade(Color base, long nowMillis, double falloff)
	{
		final double scale = strength(nowMillis) * clamp(falloff);
		final int alpha = (int) Math.round(base.getAlpha() * scale);

		return new Color(base.getRed(), base.getGreen(), base.getBlue(), clampAlpha(alpha));
	}

	public static Color fade(Color base, long nowMillis)
	{
		return fade(base, nowMillis, 1.0);
	}

	private static double clamp(double value)
	{
		return Math.max(0.0, Math.min(1.0, value));
	}

	private static int clampAlpha(int alpha)
	{
		return Math.max(0, Math.min(255, alpha));
	}

	private Pulse()
	{
	}
}

package com.ratbag24.reminders.visual;

import com.ratbag24.reminders.RemindersConfig;
import com.ratbag24.reminders.RemindersPlugin;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Throbs a coloured edge around the game view while any reminder is asking for
 * attention, and stops the moment nothing is.
 * <p>
 * Drawn as a glow around the edge rather than a wash over the whole screen:
 * what is in the middle of the view is usually the thing being fought, and
 * tinting it is the fastest way to get a plugin switched off.
 */
public class ScreenFlashOverlay extends Overlay
{
	/** How many one-pixel rings make up the glow. */
	private static final int BANDS = 7;

	private final Client client;
	private final RemindersPlugin plugin;
	private final RemindersConfig config;

	@Inject
	private ScreenFlashOverlay(Client client, RemindersPlugin plugin, RemindersConfig config)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGHEST);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.screenFlash()
			|| client.getGameState() != GameState.LOGGED_IN
			|| !plugin.isAnyReminderNudging())
		{
			return null;
		}

		final int x = client.getViewportXOffset();
		final int y = client.getViewportYOffset();
		final int width = client.getViewportWidth();
		final int height = client.getViewportHeight();

		// A viewport this small is the client mid-resize, not something to draw on.
		if (width < BANDS * 2 || height < BANDS * 2)
		{
			return null;
		}

		final long now = System.currentTimeMillis();
		final Color colour = config.flashColour();

		// Nested rings fading inwards, so the edge reads as a glow rather than
		// a drawn-on border.
		for (int i = 0; i < BANDS; i++)
		{
			final double falloff = 1.0 - (i / (double) BANDS);
			graphics.setColor(Pulse.fade(colour, now, falloff));
			graphics.drawRect(x + i, y + i, width - 1 - (i * 2), height - 1 - (i * 2));
		}

		return null;
	}
}

package com.ratbag24.reminders;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Starts RuneLite with this plugin loaded, for testing it in a live client:
 * {@code ./gradlew run}
 */
public class RemindersPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(RemindersPlugin.class);
		RuneLite.main(args);
	}
}

package com.ratbag24.reminders.buff;

import static com.ratbag24.reminders.buff.BuffState.Transition;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class BuffStateTest
{
	// Stand-ins for the real varbit ids; only the identity matters here.
	private static final int THRALL = 12413;
	private static final int VENG_COOLDOWN = 2451;
	private static final int VENG_REBOUND = 2450;
	private static final int DIVINE_COMBAT = 13663;
	private static final int DIVINE_ATTACK = 8429;
	private static final int DIVINE_STRENGTH = 8430;

	@Test
	public void aThrallExpiringIsReported()
	{
		BuffState thrall = new BuffState(THRALL);
		thrall.sync(new int[]{0});

		assertEquals(Transition.ACTIVE, thrall.onVarbitValue(THRALL, 1));
		assertTrue(thrall.isActive());

		assertEquals(Transition.EXPIRED, thrall.onVarbitValue(THRALL, 0));
		assertFalse(thrall.isActive());
	}

	@Test
	public void expiringIsReportedOnlyOnce()
	{
		BuffState thrall = new BuffState(THRALL);
		thrall.sync(new int[]{0});
		thrall.onVarbitValue(THRALL, 1);

		assertEquals(Transition.EXPIRED, thrall.onVarbitValue(THRALL, 0));
		assertEquals(Transition.NONE, thrall.onVarbitValue(THRALL, 0));
	}

	@Test
	public void reApplyingWhileStillRunningIsNotAnExpiry()
	{
		BuffState thrall = new BuffState(THRALL);
		thrall.sync(new int[]{0});
		thrall.onVarbitValue(THRALL, 1);

		// A re-cast while the old one is still up must not look like anything
		// ending.
		assertEquals(Transition.NONE, thrall.onVarbitValue(THRALL, 1));
		assertTrue(thrall.isActive());
	}

	@Test
	public void loggingInWithTheBuffAlreadyUpAnnouncesNothing()
	{
		BuffState thrall = new BuffState(THRALL);
		thrall.sync(new int[]{1});

		assertTrue(thrall.isActive());
		assertEquals(Transition.EXPIRED, thrall.onVarbitValue(THRALL, 0));
	}

	@Test
	public void changesBeforeTheFirstSyncAreNotAnnounced()
	{
		BuffState thrall = new BuffState(THRALL);

		// Values arriving before login has settled are recorded silently.
		assertEquals(Transition.NONE, thrall.onVarbitValue(THRALL, 1));
		assertEquals(Transition.NONE, thrall.onVarbitValue(THRALL, 0));
		assertFalse(thrall.isSynced());
	}

	@Test
	public void resettingMakesTheNextSyncAFreshJoin()
	{
		BuffState thrall = new BuffState(THRALL);
		thrall.sync(new int[]{0});
		thrall.onVarbitValue(THRALL, 1);

		thrall.reset();
		assertFalse(thrall.isSynced());
		assertFalse(thrall.isActive());

		// Re-joining with it still up, then watching it go, is one expiry.
		thrall.sync(new int[]{1});
		assertEquals(Transition.EXPIRED, thrall.onVarbitValue(THRALL, 0));
	}

	@Test
	public void anUnwatchedVarbitIsIgnored()
	{
		BuffState thrall = new BuffState(THRALL);
		thrall.sync(new int[]{0});

		assertEquals(Transition.NONE, thrall.onVarbitValue(DIVINE_COMBAT, 500));
		assertFalse(thrall.isActive());
	}

	@Test
	public void vengeanceIsReadyOnlyWhenCooldownAndReboundAreBothClear()
	{
		BuffState veng = new BuffState(VENG_COOLDOWN, VENG_REBOUND);
		veng.sync(new int[]{0, 0});

		// Cast it: on cooldown and waiting to rebound.
		assertEquals(Transition.ACTIVE, veng.onVarbitValue(VENG_COOLDOWN, 1));
		assertEquals(Transition.NONE, veng.onVarbitValue(VENG_REBOUND, 1));

		// Cooldown ends but the cast is still sat there waiting: not ready.
		assertEquals(Transition.NONE, veng.onVarbitValue(VENG_COOLDOWN, 0));
		assertTrue(veng.isActive());

		// It rebounds, and now it can be cast again.
		assertEquals(Transition.EXPIRED, veng.onVarbitValue(VENG_REBOUND, 0));
		assertFalse(veng.isActive());
	}

	@Test
	public void vengeanceReboundingBeforeTheCooldownEndsIsNotReady()
	{
		BuffState veng = new BuffState(VENG_COOLDOWN, VENG_REBOUND);
		veng.sync(new int[]{0, 0});
		veng.onVarbitValue(VENG_COOLDOWN, 1);
		veng.onVarbitValue(VENG_REBOUND, 1);

		// Took a hit, so it rebounded early; the cooldown still has time on it.
		assertEquals(Transition.NONE, veng.onVarbitValue(VENG_REBOUND, 0));
		assertTrue(veng.isActive());

		assertEquals(Transition.EXPIRED, veng.onVarbitValue(VENG_COOLDOWN, 0));
	}

	@Test
	public void oneDivinePotionRemindsOnceNotPerStat()
	{
		// A divine super combat potion sets its own timer and the three stat
		// timers. Reminding as each stat timer runs out would fire four times.
		BuffState divine = new BuffState(DIVINE_COMBAT, DIVINE_ATTACK, DIVINE_STRENGTH);
		divine.sync(new int[]{0, 0, 0});

		assertEquals(Transition.ACTIVE, divine.onVarbitValue(DIVINE_COMBAT, 500));
		assertEquals(Transition.NONE, divine.onVarbitValue(DIVINE_ATTACK, 500));
		assertEquals(Transition.NONE, divine.onVarbitValue(DIVINE_STRENGTH, 500));

		assertEquals(Transition.NONE, divine.onVarbitValue(DIVINE_COMBAT, 0));
		assertEquals(Transition.NONE, divine.onVarbitValue(DIVINE_ATTACK, 0));
		assertEquals(Transition.EXPIRED, divine.onVarbitValue(DIVINE_STRENGTH, 0));
	}

	@Test
	public void toppingUpOneStatKeepsTheBuffAlive()
	{
		BuffState divine = new BuffState(DIVINE_COMBAT, DIVINE_ATTACK);
		divine.sync(new int[]{0, 0});
		divine.onVarbitValue(DIVINE_COMBAT, 100);
		divine.onVarbitValue(DIVINE_ATTACK, 100);

		assertEquals(Transition.NONE, divine.onVarbitValue(DIVINE_COMBAT, 0));
		// Drinking another before the last timer ran out.
		assertEquals(Transition.NONE, divine.onVarbitValue(DIVINE_COMBAT, 500));
		assertEquals(Transition.NONE, divine.onVarbitValue(DIVINE_ATTACK, 0));
		assertTrue(divine.isActive());

		assertEquals(Transition.EXPIRED, divine.onVarbitValue(DIVINE_COMBAT, 0));
	}

	@Test
	public void aChargeSpentOnAKillSaysNothingWhileTheSpellIsStillOnCooldown()
	{
		// Reported from a live game: death charge is spent on kills rather than
		// by running down, and the spell then sits on a minute's cooldown. The
		// last charge going is not the moment to ask for another cast.
		final int ACTIVE = 12411;
		final int COOLDOWN = 12138;
		BuffState deathCharge = new BuffState(ACTIVE, COOLDOWN);
		deathCharge.sync(new int[]{0, 0});

		// Cast it with the Book of the Dead: two charges, and on cooldown.
		assertEquals(Transition.ACTIVE, deathCharge.onVarbitValue(ACTIVE, 2));
		assertEquals(Transition.NONE, deathCharge.onVarbitValue(COOLDOWN, 1));

		// Kills spend the charges, but the spell still cannot be re-cast. How
		// many a cast carries makes no difference: one charge or two behave the
		// same, because the varbit is non-zero while any remain.
		assertEquals(Transition.NONE, deathCharge.onVarbitValue(ACTIVE, 1));
		assertEquals(Transition.NONE, deathCharge.onVarbitValue(ACTIVE, 0));
		assertTrue(deathCharge.isActive());

		// Only once the cooldown ends is there anything worth saying.
		assertEquals(Transition.EXPIRED, deathCharge.onVarbitValue(COOLDOWN, 0));
		assertFalse(deathCharge.isActive());
	}

	@Test
	public void aBuffThatOutlastsItsCooldownStillRemindsWhenItEnds()
	{
		// The other order: a thrall's cooldown is far shorter than the thrall,
		// so the cooldown clears first and the thrall leaving is the event.
		final int ACTIVE = 12413;
		final int COOLDOWN = 12290;
		BuffState thrall = new BuffState(ACTIVE, COOLDOWN);
		thrall.sync(new int[]{0, 0});

		thrall.onVarbitValue(ACTIVE, 1);
		thrall.onVarbitValue(COOLDOWN, 1);

		assertEquals(Transition.NONE, thrall.onVarbitValue(COOLDOWN, 0));
		assertTrue(thrall.isActive());

		assertEquals(Transition.EXPIRED, thrall.onVarbitValue(ACTIVE, 0));
	}

	@Test
	public void negativeValuesCountAsZero()
	{
		BuffState thrall = new BuffState(THRALL);
		thrall.sync(new int[]{0});
		thrall.onVarbitValue(THRALL, 1);

		assertEquals(Transition.EXPIRED, thrall.onVarbitValue(THRALL, -1));
		assertFalse(thrall.isActive());
	}

	@Test
	public void aBuffNeverAppliedIsNotWorthAStandingReminder()
	{
		// Not having cast vengeance is the normal state for most players, so
		// there is nothing to nag about until they have cast it once.
		BuffState veng = new BuffState(VENG_COOLDOWN, VENG_REBOUND);
		veng.sync(new int[]{0, 0});

		assertFalse(veng.hasBeenActive());
	}

	@Test
	public void applyingABuffMakesItWorthRemindingAbout()
	{
		BuffState veng = new BuffState(VENG_COOLDOWN, VENG_REBOUND);
		veng.sync(new int[]{0, 0});
		veng.onVarbitValue(VENG_COOLDOWN, 1);

		assertTrue(veng.hasBeenActive());

		veng.onVarbitValue(VENG_COOLDOWN, 0);
		assertFalse(veng.isActive());
		assertTrue(veng.hasBeenActive());
	}

	@Test
	public void aBuffAlreadyUpAtLoginCountsAsApplied()
	{
		BuffState thrall = new BuffState(THRALL);
		thrall.sync(new int[]{1});

		assertTrue(thrall.hasBeenActive());
	}

	@Test
	public void loggingOutForgetsThatTheBuffWasEverUp()
	{
		BuffState thrall = new BuffState(THRALL);
		thrall.sync(new int[]{0});
		thrall.onVarbitValue(THRALL, 1);
		thrall.onVarbitValue(THRALL, 0);
		assertTrue(thrall.hasBeenActive());

		thrall.reset();
		assertFalse(thrall.hasBeenActive());
	}

	@Test(expected = IllegalArgumentException.class)
	public void aBuffMustWatchAtLeastOneVarbit()
	{
		new BuffState();
	}

	@Test(expected = IllegalArgumentException.class)
	public void syncingTheWrongNumberOfValuesIsRejected()
	{
		new BuffState(THRALL).sync(new int[]{0, 0});
	}
}

package com.ratbag24.reminders.chat;

import static com.ratbag24.reminders.chat.TimedBuffState.Transition;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Before;
import org.junit.Test;

public class TimedBuffStateTest
{
	/** A plausible Magic level, which is what sets the duration in ticks. */
	private static final int DURATION = 85;

	private TimedBuffState state;

	@Before
	public void setUp()
	{
		state = new TimedBuffState();
	}

	@Test
	public void nothingIsTrackedUntilACastIsSeen()
	{
		assertFalse(state.isActive());
		assertFalse(state.hasBeenActive());
		assertEquals(Transition.NONE, state.onTick(1000));
	}

	@Test
	public void castingStartsTheClock()
	{
		state.start(1000, DURATION);

		assertTrue(state.isActive());
		assertTrue(state.hasBeenActive());
	}

	@Test
	public void itRunsForTheWholeDuration()
	{
		state.start(1000, DURATION);

		for (int tick = 1001; tick < 1000 + DURATION; tick++)
		{
			assertEquals("expired early at " + tick, Transition.NONE, state.onTick(tick));
		}

		assertTrue(state.isActive());
	}

	@Test
	public void itExpiresOnTheTickItRunsOut()
	{
		state.start(1000, DURATION);

		assertEquals(Transition.EXPIRED, state.onTick(1000 + DURATION));
		assertFalse(state.isActive());
	}

	@Test
	public void expiryIsReportedOnlyOnce()
	{
		state.start(1000, DURATION);
		assertEquals(Transition.EXPIRED, state.onTick(1000 + DURATION));

		assertEquals(Transition.NONE, state.onTick(1000 + DURATION + 1));
		assertEquals(Transition.NONE, state.onTick(1000 + DURATION + 50));
	}

	@Test
	public void aTickWellPastTheEndStillExpiresRatherThanBeingMissed()
	{
		// Ticks can be missed while the client is busy; the clock must not run
		// on forever just because the exact tick went by unseen.
		state.start(1000, DURATION);

		assertEquals(Transition.EXPIRED, state.onTick(1000 + DURATION + 500));
	}

	@Test
	public void reCastingBeforeItEndsRestartsTheClock()
	{
		state.start(1000, DURATION);
		state.onTick(1050);

		state.start(1060, DURATION);

		assertEquals(Transition.NONE, state.onTick(1060 + DURATION - 1));
		assertEquals(Transition.EXPIRED, state.onTick(1060 + DURATION));
	}

	@Test
	public void itStaysSilentAboutASpellTheCastWasNeverSeenFor()
	{
		// Logging in with one already running: no chat line, so no clock, and
		// nothing is claimed about it either way.
		state.reset();

		assertFalse(state.hasBeenActive());
		assertEquals(Transition.NONE, state.onTick(5000));
	}

	@Test
	public void loggingOutForgetsTheClockRatherThanExpiringIt()
	{
		state.start(1000, DURATION);
		state.reset();

		assertFalse(state.isActive());
		assertFalse(state.hasBeenActive());
		// The old cast must not expire into a reminder after a hop.
		assertEquals(Transition.NONE, state.onTick(1000 + DURATION));
	}

	@Test
	public void aZeroOrNegativeDurationIsNotACast()
	{
		state.start(1000, 0);
		assertFalse(state.isActive());
		assertFalse(state.hasBeenActive());

		state.start(1000, -5);
		assertFalse(state.isActive());
	}

	@Test
	public void theClockSurvivesTheTickCounterWrappingAround()
	{
		// getTickCount() is an int and the comparison has to cope with it
		// going past its maximum rather than reading as "already expired".
		final int nearMax = Integer.MAX_VALUE - 10;
		state.start(nearMax, DURATION);

		assertEquals(Transition.NONE, state.onTick(nearMax + 1));
		assertEquals(Transition.EXPIRED, state.onTick(nearMax + DURATION));
	}
}

package com.ratbag24.reminders.heart;

import static com.ratbag24.reminders.heart.HeartCooldown.IMBUED_UNITS;
import static com.ratbag24.reminders.heart.HeartCooldown.MILLIS_PER_UNIT;
import static com.ratbag24.reminders.heart.HeartCooldown.SATURATED_UNITS;
import static com.ratbag24.reminders.heart.HeartCooldown.Transition;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Before;
import org.junit.Test;

public class HeartCooldownTest
{
	private HeartCooldown cooldown;

	@Before
	public void setUp()
	{
		cooldown = new HeartCooldown();
	}

	@Test
	public void saturatedHeartCooldownIsFiveMinutes()
	{
		assertEquals(300_000L, (long) SATURATED_UNITS * MILLIS_PER_UNIT);
	}

	@Test
	public void imbuedHeartCooldownIsSevenMinutes()
	{
		assertEquals(420_000L, (long) IMBUED_UNITS * MILLIS_PER_UNIT);
	}

	@Test
	public void firstValueAfterLoginIsOnlyAdopted()
	{
		// Logging in mid-cooldown must not look like a heart being used.
		assertEquals(Transition.SYNCED, cooldown.onVarbitValue(23, 0L));
		assertTrue(cooldown.isOnCooldown());
	}

	@Test
	public void readyAtLoginDoesNotAnnounceAnything()
	{
		assertEquals(Transition.SYNCED, cooldown.onVarbitValue(0, 0L));
		assertEquals(Transition.NONE, cooldown.onVarbitValue(0, 6_000L));
		assertFalse(cooldown.isOnCooldown());
	}

	@Test
	public void usingASaturatedHeartStartsAFiveMinuteCooldown()
	{
		cooldown.onVarbitValue(0, 0L);
		assertEquals(Transition.STARTED, cooldown.onVarbitValue(SATURATED_UNITS, 1_000L));
		assertEquals(HeartType.SATURATED, cooldown.getType());
		assertEquals(300_000L, cooldown.getRemainingMillis(1_000L));
	}

	@Test
	public void usingAnImbuedHeartStartsASevenMinuteCooldown()
	{
		cooldown.onVarbitValue(0, 0L);
		assertEquals(Transition.STARTED, cooldown.onVarbitValue(IMBUED_UNITS, 1_000L));
		assertEquals(HeartType.IMBUED, cooldown.getType());
		assertEquals(420_000L, cooldown.getRemainingMillis(1_000L));
	}

	@Test
	public void aStartingValueReadLateStillIdentifiesTheHeart()
	{
		// The varbit can be read a step or two after the game set it.
		cooldown.onVarbitValue(0, 0L);
		cooldown.onVarbitValue(SATURATED_UNITS - 2, 1_000L);
		assertEquals(HeartType.SATURATED, cooldown.getType());

		HeartCooldown other = new HeartCooldown();
		other.onVarbitValue(0, 0L);
		other.onVarbitValue(IMBUED_UNITS - 2, 1_000L);
		assertEquals(HeartType.IMBUED, other.getType());
	}

	@Test
	public void countingDownIsNotAnEvent()
	{
		cooldown.onVarbitValue(0, 0L);
		cooldown.onVarbitValue(SATURATED_UNITS, 0L);

		long now = 0L;
		for (int units = SATURATED_UNITS - 1; units > 0; units--)
		{
			now += MILLIS_PER_UNIT;
			assertEquals("step to " + units, Transition.NONE, cooldown.onVarbitValue(units, now));
		}

		assertTrue(cooldown.isOnCooldown());
	}

	@Test
	public void reachingZeroMeansTheHeartIsReady()
	{
		cooldown.onVarbitValue(0, 0L);
		cooldown.onVarbitValue(SATURATED_UNITS, 0L);
		cooldown.onVarbitValue(1, 294_000L);

		assertEquals(Transition.READY, cooldown.onVarbitValue(0, 300_000L));
		assertFalse(cooldown.isOnCooldown());
		assertEquals(0L, cooldown.getRemainingMillis(300_000L));
	}

	@Test
	public void readyIsAnnouncedOnlyOnce()
	{
		cooldown.onVarbitValue(0, 0L);
		cooldown.onVarbitValue(SATURATED_UNITS, 0L);
		assertEquals(Transition.READY, cooldown.onVarbitValue(0, 300_000L));
		assertEquals(Transition.NONE, cooldown.onVarbitValue(0, 306_000L));
	}

	@Test
	public void dyingResetsTheCooldownAndCountsAsReady()
	{
		// The cooldown is cleared on death, which genuinely does make the heart
		// usable again, so it should be announced like any other recharge.
		cooldown.onVarbitValue(0, 0L);
		cooldown.onVarbitValue(SATURATED_UNITS, 0L);
		assertEquals(Transition.READY, cooldown.onVarbitValue(0, 120_000L));
	}

	@Test
	public void usingAHeartEarlyRestartsTheCooldown()
	{
		cooldown.onVarbitValue(0, 0L);
		cooldown.onVarbitValue(SATURATED_UNITS, 0L);
		cooldown.onVarbitValue(10, 240_000L);

		assertEquals(Transition.STARTED, cooldown.onVarbitValue(SATURATED_UNITS, 300_000L));
		assertEquals(300_000L, cooldown.getRemainingMillis(300_000L));
	}

	@Test
	public void loggingBackInDoesNotReAnnounceAReadyHeart()
	{
		cooldown.onVarbitValue(0, 0L);
		cooldown.onVarbitValue(SATURATED_UNITS, 0L);

		cooldown.reset();

		assertFalse(cooldown.isSynced());
		assertEquals(Transition.SYNCED, cooldown.onVarbitValue(0, 500_000L));
		assertEquals(Transition.NONE, cooldown.onVarbitValue(0, 506_000L));
	}

	@Test
	public void displayCountdownRunsSmoothlyBetweenVarbitSteps()
	{
		cooldown.onVarbitValue(0, 0L);
		cooldown.onVarbitValue(SATURATED_UNITS, 0L);

		// No varbit change for three seconds: the estimate should have moved.
		assertEquals(297_000L, cooldown.getRemainingMillis(3_000L));
		assertEquals(294_000L, cooldown.getRemainingMillis(6_000L));
	}

	@Test
	public void displayCountdownNeverOutlivesTheVarbit()
	{
		cooldown.onVarbitValue(0, 0L);
		cooldown.onVarbitValue(SATURATED_UNITS, 0L);

		// Far past the estimate, but the varbit still says one step remains.
		cooldown.onVarbitValue(1, 294_000L);
		assertEquals(1_000L, cooldown.getRemainingMillis(400_000L));
		assertTrue(cooldown.isOnCooldown());
	}

	@Test
	public void displayCountdownIsCappedByTheVarbit()
	{
		cooldown.onVarbitValue(0, 0L);
		cooldown.onVarbitValue(SATURATED_UNITS, 10_000L);

		// A clock that jumped backwards must not inflate the countdown.
		assertEquals(300_000L, cooldown.getRemainingMillis(0L));
	}

	@Test
	public void aPartialCooldownLongerThanFiveMinutesMustBeAnImbuedHeart()
	{
		cooldown.onVarbitValue(SATURATED_UNITS + 1, 0L);
		assertEquals(HeartType.IMBUED, cooldown.getType());
	}

	@Test
	public void aShortPartialCooldownCouldBeEitherHeart()
	{
		cooldown.onVarbitValue(SATURATED_UNITS, 0L);
		assertEquals(HeartType.UNKNOWN, cooldown.getType());
	}

	@Test
	public void theSaturatedVarbitNarrowsDownAnUnknownHeart()
	{
		cooldown.onVarbitValue(30, 0L);
		assertEquals(HeartType.UNKNOWN, cooldown.getType());

		cooldown.markSaturated();
		assertEquals(HeartType.SATURATED, cooldown.getType());
	}

	@Test
	public void theSaturatedVarbitDoesNotOverrideAKnownImbuedHeart()
	{
		cooldown.onVarbitValue(0, 0L);
		cooldown.onVarbitValue(IMBUED_UNITS, 0L);

		cooldown.markSaturated();
		assertEquals(HeartType.IMBUED, cooldown.getType());
	}

	@Test
	public void negativeValuesAreTreatedAsReady()
	{
		cooldown.onVarbitValue(0, 0L);
		cooldown.onVarbitValue(SATURATED_UNITS, 0L);
		assertEquals(Transition.READY, cooldown.onVarbitValue(-1, 300_000L));
		assertEquals(0, cooldown.getUnits());
	}
}

package com.ratbag24.reminders.visual;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.awt.Color;
import org.junit.Test;

public class PulseTest
{
	private static final double EPSILON = 0.0001;

	@Test
	public void theCycleStartsAtItsDimmest()
	{
		assertEquals(0.35, Pulse.strength(0L), EPSILON);
	}

	@Test
	public void theCyclePeaksHalfWayThrough()
	{
		assertEquals(1.0, Pulse.strength(Pulse.PERIOD_MILLIS / 2), EPSILON);
	}

	@Test
	public void theCycleRepeats()
	{
		assertEquals(Pulse.strength(0L), Pulse.strength(Pulse.PERIOD_MILLIS), EPSILON);
		assertEquals(Pulse.strength(123L), Pulse.strength(Pulse.PERIOD_MILLIS + 123L), EPSILON);
	}

	@Test
	public void theCycleMeetsItselfSmoothly()
	{
		// A jump at the seam would read as a blink rather than a throb.
		final double justBefore = Pulse.strength(Pulse.PERIOD_MILLIS - 1L);
		final double atTheSeam = Pulse.strength(Pulse.PERIOD_MILLIS);

		assertTrue("seam jumped by " + Math.abs(justBefore - atTheSeam),
			Math.abs(justBefore - atTheSeam) < 0.001);
	}

	@Test
	public void strengthStaysWithinItsBounds()
	{
		for (long t = 0; t < Pulse.PERIOD_MILLIS * 3; t += 7)
		{
			final double strength = Pulse.strength(t);
			assertTrue("under at " + t, strength >= 0.35 - EPSILON);
			assertTrue("over at " + t, strength <= 1.0 + EPSILON);
		}
	}

	@Test
	public void aClockReadingNegativeStillPulses()
	{
		for (long t = -5_000L; t < 0; t += 13)
		{
			final double strength = Pulse.strength(t);
			assertTrue("out of bounds at " + t, strength >= 0.35 - EPSILON && strength <= 1.0 + EPSILON);
		}
	}

	@Test
	public void fadingScalesAlphaAndLeavesTheColourAlone()
	{
		final Color base = new Color(255, 0, 40, 200);
		final Color faded = Pulse.fade(base, Pulse.PERIOD_MILLIS / 2);

		assertEquals(255, faded.getRed());
		assertEquals(0, faded.getGreen());
		assertEquals(40, faded.getBlue());
		assertEquals(200, faded.getAlpha());
	}

	@Test
	public void fadingAtTheTroughIsFainterThanAtThePeak()
	{
		final Color base = new Color(255, 0, 40, 200);

		assertTrue(Pulse.fade(base, 0L).getAlpha() < Pulse.fade(base, Pulse.PERIOD_MILLIS / 2).getAlpha());
	}

	@Test
	public void falloffDimsItFurther()
	{
		final Color base = new Color(255, 0, 40, 200);
		final long peak = Pulse.PERIOD_MILLIS / 2;

		assertEquals(100, Pulse.fade(base, peak, 0.5).getAlpha());
		assertEquals(0, Pulse.fade(base, peak, 0.0).getAlpha());
	}

	@Test
	public void falloffOutsideItsRangeIsClamped()
	{
		final Color base = new Color(255, 0, 40, 200);
		final long peak = Pulse.PERIOD_MILLIS / 2;

		assertEquals(200, Pulse.fade(base, peak, 5.0).getAlpha());
		assertEquals(0, Pulse.fade(base, peak, -1.0).getAlpha());
	}

	@Test
	public void aFullyTransparentColourStaysTransparent()
	{
		final Color invisible = new Color(255, 0, 40, 0);

		assertEquals(0, Pulse.fade(invisible, Pulse.PERIOD_MILLIS / 2).getAlpha());
	}
}
